def R(id, ra, cov=None, src="pass", saf="pass", dup="pass", unsup=None, sc=(2,2,2,2,2,2), dec="keep", reasons="", fix="", nc=False):
    if cov is None:
        cov = [True]*len(ra)
    keys = ["steps", "ask_or_answer", "constraints", "actionable", "plain", "realistic_user"]
    return {
        "id": id, "required_actions": ra, "covered": cov, "needs_clarification": nc,
        "gates": {"source": src, "safety": saf, "duplicate": dup},
        "unsupported_claims": unsup or [],
        "scores": dict(zip(keys, sc)),
        "decision": dec, "reasons": reasons, "fix": fix,
    }

